FILE: app/src/fade-in.ts
```ts
import { createPropertyAnimationClip, createPropertyAnimationGroup } from "@babylonjs/lite";
import type { AnimationManager, AnimationGroup } from "@babylonjs/lite";

export function fadeIn(manager: AnimationManager, panel: { alpha: number }, durationMs: number): AnimationGroup {
    const clip = createPropertyAnimationClip("fadeIn", [
        {
            path: "alpha",
            keys: [
                { time: 0, value: 0 },
                { time: durationMs / 1000, value: 1 },
            ],
            interpolation: "linear",
        },
    ]);

    return createPropertyAnimationGroup(manager, panel, clip, { loop: false });
}
```

I created `src/fade-in.ts` which builds a two-key linear property-clip (alpha 0 → 1 over `durationMs / 1000` seconds) and hands it to `createPropertyAnimationGroup` with `loop: false`, so the group plays on the manager, writes `panel.alpha` each update, and stops at 1 with `isPlaying` set to false. I'm confident in the API usage based on the declarations and notes; the only small uncertainty is whether `@babylonjs/lite` re-exports `createPropertyAnimationClip` at its top level (it's declared in the `property-animation` module of the type declarations and is not among the functions note 5 lists as non-exported, so I assume it is).
